                input.hash(&mut h);
                let val = h.finish();
                println!("foldhash seed {} input {} {} {}", seed, input, val, b64_6_le(val));
            }
        }
    }
    // Try std DefaultHasher
    {
        use std::collections::hash_map::DefaultHasher;
        for (input, expected) in vec![("a.css","CK9avG")] {
            let mut h = DefaultHasher::new();
            input.hash(&mut h);
            println!("DefaultHasher input {} {} {}", input, h.finish(), b64_6_le(h.finish()));
        }
    }
}
