		case "--sourcemap":
			a.sourcemap = true
			i++
		case "-t", "--targets":
			if i+1 >= len(args) {
				printErrorAndExit("error: The argument '--targets <TARGETS>' requires a value but none was supplied\n\nFor more information try --help\n", 2)
			}
			v := args[i+1]
			a.targets = &v
			i += 2
		case "-h", "--help":
			fmt.Print(helpText)
			os.Exit(0)
		case "-V", "--version":
			fmt.Println(version)
			os.Exit(0)
		case "--":
			// end of flags
			a.inputFiles = append(a.inputFiles, args[i+1:]...)
			i = len(args)
		default:
			if strings.HasPrefix(arg, "-") {
				// Check for combined form like --css-modules=foo
				if strings.HasPrefix(arg, "--css-modules=") {
					v := strings.TrimPrefix(arg, "--css-modules=")
					a.cssModules = &v
					i++
					continue
				}
				if strings.HasPrefix(arg, "--css-modules-pattern=") {
					v := strings.TrimPrefix(arg, "--css-modules-pattern=")
					a.cssModulesPattern = &v
					i++
					continue
				}
				if strings.HasPrefix(arg, "--output-dir=") {
					v := strings.TrimPrefix(arg, "--output-dir=")
					a.outputDir = &v
					i++
					continue
				}
				if strings.HasPrefix(arg, "--output-file=") {
					v := strings.TrimPrefix(arg, "--output-file=")
					a.outputFile = &v
					i++
					continue
				}
				if strings.HasPrefix(arg, "--targets=") {
					v := strings.TrimPrefix(arg, "--targets=")
					a.targets = &v
					i++
					continue
				}
