func isKnownFlag(s string) bool {
	known := []string{"--browserslist", "--bundle", "--css-modules", "--css-modules-dashed-idents", "--css-modules-pattern", "--custom-media", "-d", "--output-dir", "--error-recovery", "-m", "--minify", "-o", "--output-file", "--sourcemap", "-t", "--targets", "-h", "--help", "-V", "--version"}
	for _, k := range known {
		if s == k {
			return true
		}
		if strings.HasPrefix(s, k+"=") {
			return true
		}
	}
	// also check for short flags combined? Not needed
	return false
}

