		printErrorAndExit("error: The following required arguments were not provided:\n    <--css-modules [<CSS_MODULES>]>\n\nUSAGE:\n    executable --css-modules-pattern <CSS_MODULES_PATTERN> <--css-modules [<CSS_MODULES>]>\n\nFor more information try --help\n", 2)
	}
