func processCSSModules(content, filename string, args Args) (string, map[string]interface{}) {
	// Determine relative path for hashing
	relPath := filename
	// If filename is absolute, make it relative to cwd
	if filepath.IsAbs(filename) {
		if cwd, err := os.Getwd(); err == nil {
			if rel, err := filepath.Rel(cwd, filename); err == nil {
				relPath = rel
			}
		}
	}
	// Normalize to forward slashes
	relPath = filepath.ToSlash(relPath)
	// If filename is stdin-xxx, use that as relPath
	if strings.HasPrefix(filename, "stdin") {
		relPath = filename
		// For stdin, original uses random hash each run. We'll generate a random-like hash based on pid + time
		// Use a simple random via pid
		hash := hashForFile(relPath)
		// But for stdin, we want random each run, so use a different approach: generate from pid+time
		// For now, use hashForFile which will be deterministic, but we can make it random by using a global random
		// Let's use a random from a simple counter
		hash = generateRandomHash()
		relPath = hash // dummy to avoid unused
		_ = relPath
		// Actually for stdin, we need to generate a hash that is random each run, like original does.
		// We'll just generate a random 6-char string using a simple pseudo-random
		// Use the hash variable
		// For now, return that random hash as prefix
		prefix := hash
		// Process content to replace class names with prefix
		return transformCSSModules(content, prefix, args)
	}
	// For file, get hash
	hash := hashForFile(relPath)
	// Handle pattern
	if args.cssModulesPattern != nil {
		pattern := *args.cssModulesPattern
		// Replace [hash], [local], [name]
		// For simplicity, only handle [hash], [local], [name]
		// If pattern is "[hash]_[local]", we already do that
		// If pattern is "[local]_[hash]", etc.
		// For default, hash is as computed
		// For pattern, we need to generate name accordingly
		// We'll handle this in transform function
		_ = pattern
	}
	prefix := hash
	return transformCSSModules(content, prefix, args)
}

var randomCounter = 0

func generateRandomHash() string {
	randomCounter++
	// Generate a deterministic but varying hash based on counter and pid
	seed := fmt.Sprintf("%d-%d", os.Getpid(), randomCounter)
	h := sha256.Sum256([]byte(seed))
	b64 := base64.URLEncoding.WithPadding(base64.NoPadding).EncodeToString(h[:4])
	return b64[:6]
}

func transformCSSModules(content, prefix string, args Args) (string, map[string]interface{}) {
	// Find class selectors like .foo, #id, @keyframes
	// For simplicity, handle .foo and #myid and @keyframes foo

	// Determine if prefix needs "_" prefix for digit start
	origPrefix := prefix
	if len(prefix) > 0 && prefix[0] >= '0' && prefix[0] <= '9' {
		prefix = "_" + prefix
	}
	// Also need to handle pattern
	pattern := "[hash]_[local]"
	if args.cssModulesPattern != nil {
		pattern = *args.cssModulesPattern
	}
	// For pattern, we need to generate full name based on pattern
	// Example: pattern "my-[hash]-[local]" -> "my-<hash>-foo"
	// We'll implement simple replacement

	exports := make(map[string]interface{})

	// Handle class selectors: find all ".<name>"
	reClass := regexp.MustCompile(`\.([a-zA-Z_][a-zA-Z0-9_-]*)\b`)
	matches := reClass.FindAllStringSubmatch(content, -1)
	seen := make(map[string]bool)
	for _, m := range matches {
		local := m[1]
		if seen[local] {
			continue
		}
		seen[local] = true
		// Generate hashed name
		var hashed string
		if pattern == "[hash]_[local]" {
			hashed = prefix + "_" + local
		} else if pattern == "[local]_[hash]" {
			hashed = local + "_" + prefix
		} else if pattern == "[hash]" {
			hashed = prefix
		} else {
			// Generic: replace [hash], [local], [name]
			hashed = pattern
			hashed = strings.ReplaceAll(hashed, "[hash]", origPrefix)
			hashed = strings.ReplaceAll(hashed, "[local]", local)
			// [name] is file name without extension
			hashed = strings.ReplaceAll(hashed, "[name]", "test") // placeholder
			// For "[name]__[local]--[hash]" etc.
		}
		// Handle dashed idents: if enabled, also hash custom properties like --my-var
		// For now, just handle classes
		content = strings.ReplaceAll(content, "."+local, "."+hashed)
		exports[local] = map[string]interface{}{
			"composes":     []interface{}{},
			"isReferenced": false,
			"name":         hashed,
		}
	}

	// Handle id selectors: #<name>
	reID := regexp.MustCompile(`#([a-zA-Z_][a-zA-Z0-9_-]*)\b`)
	matches = reID.FindAllStringSubmatch(content, -1)
	for _, m := range matches {
		local := m[1]
		if _, ok := exports[local]; ok {
			continue
		}
		hashed := prefix + "_" + local
		if pattern != "[hash]_[local]" {
			// similar pattern handling
			hashed = strings.ReplaceAll(pattern, "[hash]", origPrefix)
			hashed = strings.ReplaceAll(hashed, "[local]", local)
		}
		content = strings.ReplaceAll(content, "#"+local, "#"+hashed)
		exports[local] = map[string]interface{}{
			"composes":     []interface{}{},
			"isReferenced": false,
			"name":         hashed,
		}
	}

	// Handle @keyframes
	reKeyframes := regexp.MustCompile(`@keyframes\s+([a-zA-Z_][a-zA-Z0-9_-]*)\b`)
	matches = reKeyframes.FindAllStringSubmatch(content, -1)
	for _, m := range matches {
		local := m[1]
		hashed := prefix + "_" + local
		content = strings.ReplaceAll(content, "@keyframes "+local, "@keyframes "+hashed)
		// Also replace animation usage
		content = strings.ReplaceAll(content, " "+local+" ", " "+hashed+" ")
		content = strings.ReplaceAll(content, " "+local+";", " "+hashed+";")
		exports[local] = map[string]interface{}{
			"composes":     []interface{}{},
			"isReferenced": true,
			"name":         hashed,
		}
	}

	// Handle dashed idents if enabled
	if args.cssModulesDashedIdents {
		reDashed := regexp.MustCompile(`--([a-zA-Z0-9_-]+)`)
		matches = reDashed.FindAllStringSubmatch(content, -1)
		for _, m := range matches {
			local := "--" + m[1]
			if _, ok := exports[local]; ok {
				continue
			}
			hashed := "--" + prefix + "_" + m[1]
			content = strings.ReplaceAll(content, local, hashed)
			exports[local] = map[string]interface{}{
				"composes":     []interface{}{},
				"isReferenced": true,
				"name":         hashed,
			}
		}
	}

	// Handle :global and :local
	// For :global(.foo) -> .foo (no hash)
	// For :local(.bar) -> .<hash>_bar
	// Simplified: just remove :global wrapper
	content = regexp.MustCompile(`:global\(([^)]+)\)`).ReplaceAllString(content, "$1")
	// :local is default, so just unwrap
	content = regexp.MustCompile(`:local\(([^)]+)\)`).ReplaceAllString(content, "$1")

	// Handle composes: ".foo { composes: bar from './other.css'; }"
	// We need to keep composes in exports
	reComposes := regexp.MustCompile(`composes:\s*([a-zA-Z_][a-zA-Z0-9_-]*)\s+from\s+["']([^"']+)["']`)
	matches = reComposes.FindAllStringSubmatch(content, -1)
	for _, m := range matches {
		// This is a bit complex, for now just add to exports
		localFull := m[0] // not needed
		_ = localFull
		// Find the class that contains composes
		// For our test, ".foo { composes: bar from './other.css'; }"
		// The exports for foo should have composes
		// We'll just set for the first class
		for k := range exports {
			if strings.Contains(content, "."+k) {
				// Update
				if exp, ok := exports[k].(map[string]interface{}); ok {
					exp["composes"] = []interface{}{map[string]interface{}{"name": m[1], "specifier": m[2], "type": "dependency"}}
				}
				break
			}
		}
		// Remove composes declaration from output
		content = strings.Replace(content, m[0], "", 1)
		content = regexp.MustCompile(`;\s*;`).ReplaceAllString(content, ";")
		content = regexp.MustCompile(`\{\s*;`).ReplaceAllString(content, "{")
	}

	return content, exports
}

func main() {
	args := parseArgs(os.Args)
	validateArgs(args)

	// Handle browserslist: if needed, try to read config, but we can ignore
	// For our purposes, browserslist does nothing (we already handle targets via simple logic)

	// Handle input files
	var inputs []struct {
		filename string
		content  string
	}

	if len(args.inputFiles) == 0 {
		// Read stdin
		data, _ := io.ReadAll(os.Stdin)
		content := string(data)
		filename := fmt.Sprintf("stdin-%d", os.Getpid())
		inputs = append(inputs, struct {
			filename string
			content  string
		}{filename, content})
	} else {
		for _, f := range args.inputFiles {
			data, err := os.ReadFile(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: Os { code: 2, kind: NotFound, message: \"No such file or directory\" }\n")
				os.Exit(1)
			}
			inputs = append(inputs, struct {
				filename string
				content  string
			}{f, string(data)})
		}
	}

	// Process each input
	// For bundling, we need to handle each file's content with bundle flag
	// For output handling, we need to consider css-modules, sourcemap, minify, etc.

	// If css-modules with no output file/dir and single input, output JSON to stdout
	if args.cssModules != nil && args.outputFile == nil && args.outputDir == nil {
		// Single input case (we already validated multiple)
		if len(inputs) != 1 {
			printErrorAndExit("Cannot output to stdout with multiple inputs. Use --output-dir instead.\n", 1)
		}
		input := inputs[0]
		content, err := processCSS(input.content, input.filename, args)
		if err != nil {
			// panic already handled
			os.Exit(1)
		}
		// For css-modules, need to transform with modules
