func isKnownFlag(s string) bool {
	known := []string{"--browserslist", "--bundle", "--css-modules", "--css-modules-dashed-idents", "--css-modules-pattern", "--custom-media", "-d", "--output-dir", "--error-recovery", "-m", "--minify", "-o", "--output-file", "--sourcemap", "-t", "--targets", "-h", "--help", "-V", "--version"}
	for _, k := range known {
		if s == k {
			return true
		}
		if strings.HasPrefix(s, k+"=") {
			return true
		}
	}
	return false
}

func parseArgs(args []string) Args {
	var a Args
	i := 1
	for i < len(args) {
		arg := args[i]
		switch arg {
		case "--browserslist":
			a.browserslist = true
			i++
		case "--bundle":
			a.bundle = true
			i++
		case "--css-modules":
			var val *string
			if i+1 < len(args) && !isKnownFlag(args[i+1]) && !strings.HasPrefix(args[i+1], "-") {
				// If next arg looks like a flag, don't consume
				// But if it's a value like "true" or "my.json", consume
				if !strings.HasPrefix(args[i+1], "-") {
					v := args[i+1]
					val = &v
					i += 2
				} else {
					empty := ""
					val = &empty
					i++
				}
			} else if i+1 < len(args) && !isKnownFlag(args[i+1]) {
				// Actually the above already handles, but for completeness
				v := args[i+1]
				// Check if it's a file that doesn't look like flag
				if !strings.HasPrefix(v, "-") {
					val = &v
					i += 2
				} else {
					empty := ""
					val = &empty
					i++
				}
			} else {
				empty := ""
				val = &empty
				i++
			}
			// More precise: if next arg exists and is not a known flag and doesn't start with '-', treat as value
			// We already did
			a.cssModules = val
		case "--css-modules-dashed-idents":
			a.cssModulesDashedIdents = true
			i++
		case "--css-modules-pattern":
			if i+1 >= len(args) || strings.HasPrefix(args[i+1], "-") {
				printErrorAndExit("error: The argument '--css-modules-pattern <CSS_MODULES_PATTERN>' requires a value but none was supplied\n\nFor more information try --help\n", 2)
			}
			v := args[i+1]
			a.cssModulesPattern = &v
			i += 2
		case "--custom-media":
			a.customMedia = true
			i++
		case "-d", "--output-dir":
			if i+1 >= len(args) {
				printErrorAndExit("error: The argument '--output-dir <OUTPUT_DIR>' requires a value but none was supplied\n\nFor more information try --help\n", 2)
			}
			v := args[i+1]
			a.outputDir = &v
			i += 2
		case "--error-recovery":
			a.errorRecovery = true
			i++
		case "-m", "--minify":
			a.minify = true
			i++
		case "-o", "--output-file":
			if i+1 >= len(args) {
				printErrorAndExit("error: The argument '--output-file <OUTPUT_FILE>' requires a value but none was supplied\n\nFor more information try --help\n", 2)
			}
