				if strings.HasPrefix(arg, "--output-file=") {
					v := strings.TrimPrefix(arg, "--output-file=")
					a.outputFile = &v
					i++
					continue
				}
				if strings.HasPrefix(arg, "--targets=") {
					v := strings.TrimPrefix(arg, "--targets=")
					a.targets = &v
					i++
					continue
				}
				printErrorAndExit(fmt.Sprintf("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `%s` as a value rather than a flag, use `-- %s`\n\nUSAGE:\n    executable [OPTIONS] [INPUT_FILE]...\n\nFor more information try --help\n", arg, arg, arg), 2)
			} else {
