	// But if next arg was not consumed, need to ensure we didn't miss
	return a
}

func validateArgs(a Args) {
	if a.browserslist && a.targets != nil {
		printErrorAndExit("error: The argument '--browserslist' cannot be used with '--targets <TARGETS>'\n\nUSAGE:\n    executable <--targets <TARGETS>|--browserslist>\n\nFor more information try --help\n", 2)
	}
	if a.outputFile != nil && a.outputDir != nil {
		printErrorAndExit("error: The argument '--output-file <OUTPUT_FILE>' cannot be used with '--output-dir <OUTPUT_DIR>'\n\nUSAGE:\n    executable <--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>\n\nFor more information try --help\n", 2)
	}
	if a.cssModulesPattern != nil && a.cssModules == nil {
