			} else {
				sources = []string{input.filename}
			}
			// Handle bundle sourcemap
			mappings := "AAAA"
			sourcesContent := []string{input.content}
			if args.bundle && strings.Contains(inputs[0].content, "@import") {
				// Need to include imported file
				reImport := regexp.MustCompile(`@import\s+["']([^"']+)["']`)
