				if len(m) > 1 {
					importPath := m[1]
					dirInput := filepath.Dir(input.filename)
					fullImport := filepath.Join(dirInput, importPath)
					if data, err := os.ReadFile(fullImport); err == nil {
						// Sources are input file and imported file, but original's order was input then imported? For bundle -o, original gave sources ["../tmp/.../a.css","../tmp/.../b.css"] with a.css first, b.css second, but output content was b.css then a.css
						sources = []string{input.filename, fullImport}
