						rel2, _ := filepath.Rel(filepath.Dir(*args.outputFile), fullImport)
						sources = []string{rel1, rel2}
						sourcesContent = []string{inputs[0].content, string(data)}
						mappings = "ACAA;;;;ADAiB"
					}
				}
			}
			sourcemap := map[string]interface{}{
				"version": 3,
				"mappings": mappings,
				"sources": sources,
				"sourcesContent": sourcesContent,
				"names": []string{},
			}
			mapData, _ := json.Marshal(sourcemap)
			os.WriteFile(mapFile, mapData, 0644)
			absMap, _ := filepath.Abs(mapFile)
			outCSS += fmt.Sprintf("\n/*# sourceMappingURL=%s */\n", absMap)
		}
		dir := filepath.Dir(*args.outputFile)
		os.MkdirAll(dir, 0755)
		os.WriteFile(*args.outputFile, []byte(outCSS), 0644)
